          const casablancaCity = await City.findOne({ name: 'Casablanca' });  

          const newAddress = new Address({      
            user_id: userId,      
            street: profile.adresse_principale,      
            city_id: casablancaCity?._id,  
            latitude: profile.latitude || null,  
